function twoSum(nums: number[], target: number): number[] {
  // Значение -> индекс, для уже просмотренных элементов
  const seen = new Map<number, number>();

  for (let i = 0; i < nums.length; i++) {
    // Какое число нужно в пару к текущему
    const need = target - nums[i];

    const j = seen.get(need);
    if (j !== undefined) {
      // Пара найдена: j — более ранний индекс
      return [j, i];
    }

    // Запоминаем текущий элемент ПОСЛЕ проверки,
    // чтобы не сложить элемент сам с собой
    seen.set(nums[i], i);
  }

  // По условию решение всегда существует
  return [];
}

// Время: O(n) — один проход
// Память: O(n) — хеш-таблица
